    "stem": "A 24-year-old man is admitted to the emergency observation ward of a District Headquarter (DHQ) hospital with clinical findings indicative of Tuberculosis Pulmonary Sputum AFB Positive Category 1. Clinical examination and investigative review confirm 2 months of daily fixed-dose RHZE followed by 4 months of daily RH under directly observed therapy. Vitals reveal blood pressure of 120/82 mm Hg, heart rate of 80/min, respiratory rate of 16/min, and temperature of 38.2C (98.7F). Diagnostic serum testing, focused physiological assessment, and targeted structural evaluations demonstrate characteristic pathophysiological hallmarks of tuberculosis pulmonary sputum afb positive category 1. Which of the following is the most appropriate next step in clinical management according to Pakistan Medical and Dental Council (PMDC) NLE guidelines?",
