    "type": "SINGLE",
    "difficulty": 4,
    "stem": "A 44-year-old man presents to the rural health center (RHC) outpatient consultation room in Sindh with clinical findings indicative of Acute Bacillary Dysentery Shigellosis with High Fever. Clinical examination and investigative review confirm oral rehydration solution, zinc supplementation, and oral ciprofloxacin or azithromycin. Vitals reveal blood pressure of 125/77 mm Hg, heart rate of 81/min, respiratory rate of 19/min, and temperature of 37.3C (98.7F). Diagnostic serum testing, focused physiological assessment, and targeted structural evaluations demonstrate characteristic pathophysiological hallmarks of acute bacillary dysentery shigellosis with high fever. Which of the following is the most appropriate next step in clinical management according to Pakistan Medical and Dental Council (PMDC) NLE guidelines?",
    "options": [
      {
        "text": "Oral broad-spectrum fluoroquinolone monotherapy without microbiological confirmation",
        "correct": false,
        "explanation": "Incorrect: Empiric fluoroquinolones risk severe adverse effects including tendonopathy and select for multidrug-resistant pathogens when unindicated."
      },
      {
        "text": "Immediate peritoneal dialysis catheter insertion during acute shock",
        "correct": false,
        "explanation": "Incorrect: Invasive abdominal catheter placement during hemodynamic instability carries severe risks of bowel laceration and peritonitis."
      },
      {
        "text": "Oral rehydration solution, zinc supplementation, and oral ciprofloxacin or azithromycin",
        "correct": true,
        "explanation": "Correct: According to established evidence-based consensus and clinical practice guidelines, the primary indicated management for this clinical scenario is oral rehydration solution, zinc supplementation, and oral ciprofloxacin or azithromycin. This directly addresses the underlying pathophysiological abnormality, optimizes therapeutic outcomes, and mitigates disease-specific morbidity."
      },
      {
        "text": "Oral methotrexate therapy without concurrent folic acid supplementation",
        "correct": false,
        "explanation": "Incorrect: Methotrexate without folate rescue markedly elevates the frequency of severe mucositis, gastrointestinal toxicity, and bone marrow failure."
      },
      {
        "text": "Diagnostic lumbar puncture prior to excluding intracranial mass effect with neuroimaging",
        "correct": false,
        "explanation": "Incorrect: Performing dural puncture in the presence of focal space-occupying lesions risks fatal transtentorial or tonsillar herniation."
      }
    ],
